module CountAlmostPalindromic(\n    input clk,\n    input rst_n,\n    input start,\n    input [4:0] char_in [0:3],\n    output reg [3:0] count,\n    output reg done\n);\n    \n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] PROCESS = 2'd1;\n    localparam [1:0] DONE    = 2'd2;\n    \n    reg [1:0] state;\n    reg [3:0] sub_str_idx;\n    reg [1:0] start_val;\n    reg [2:0] len_val;\n    reg [4:0] extracted_chars [0:3];\n    wire is_almost;\n    \n    // Substring extraction\n    always @(*) begin\n        start_val = 2'd0;\n        len_val = 3'd0;\n        extracted_chars[0] = 5'd0;\n        extracted_chars[1] = 5'd0;\n        extracted_chars[2] = 5'd0;\n        extracted_chars[3] = 5'd0;\n        \n        case (sub_str_idx)\n            4'd0: begin start_val = 2'd0; len_val = 3'd1; end\n            4'd1: begin start_val = 2'd1; len_val = 3'd1; end\n            4'd2: begin start_val = 2'd2; len_val = 3'd1; end\n            4'd3: begin start_val = 2'd3; len_val = 3'd1; end\n            4'd4: begin start_val = 2'd0; len_val = 3'd2; end\n            4'd5: begin start_val = 2'd1; len_val = 3'd2; end\n            4'd6: begin start_val = 2'd2; len_val = 3'd2; end\n            4'd7: begin start_val = 2'd0; len_val = 3'd3; end\n            4'd8: begin start_val = 2'd1; len_val = 3'd3; end\n            4'd9: begin start_val = 2'd0; len_val = 3'd4; end\n            default: ;\n        endcase\n        \n        // Extract characters\n        if (len_val >= 3'd1) extracted_chars[0] = char_in[start_val];\n        if (len_val >= 3'd2) extracted_chars[1] = char_in[start_val + 1'd1];\n        if (len_val >= 3'd3) extracted_chars[2] = char_in[start_val + 2'd2];\n        if (len_val >= 3'd4) extracted_chars[3] = char_in[start_val + 2'd3];\n    end\n    \n    // Almost palindrome check\n    assign is_almost =\n        (len_val == 3'd1) ? 1'b1 :\n        (len_val == 3'd2) ? (extracted_chars[0] == extracted_chars[1]) :\n        (len_val == 3'd3) ? (\n            (extracted_chars[0] == extracted_chars[2]) ||\n            (extracted_chars[0] == extracted_chars[1]) ||\n            (extracted_chars[1] == extracted_chars[2])\n        ) :\n        (len_val == 3'd4) ? (\n            ((extracted_chars[0] == extracted_chars[3]) && (extracted_chars[1] == extracted_chars[2])) ||\n            ((extracted_chars[0] == extracted_chars[2]) && (extracted_chars[1] == extracted_chars[3])) ||\n            ((extracted_chars[0] == extracted_chars[1]) && (extracted_chars[2] == extracted_chars[3]))\n        ) : 1'b0;\n    \n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            count <= 4'd0;\n            done <= 1'b0;\n            sub_str_idx <= 4'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        count <= 4'd0;\n                        sub_str_idx <= 4'd0;\n                        state <= PROCESS;\n                    end\n                end\n                \n                PROCESS: begin\n                    if (is_almost) count <= count + 4'd1;\n                    \n                    if (sub_str_idx == 4'd9) begin\n                        state <= DONE;\n                    end else begin\n                        sub_str_idx <= sub_str_idx + 4'd1;\n                    end\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n    \nendmodule